import math
import unittest

from solution import classify_run


class ClassifyRunTests(unittest.TestCase):
    def test_constant_sequences(self):
        self.assertEqual(classify_run([]), "constant")
        self.assertEqual(classify_run([4]), "constant")
        self.assertEqual(classify_run([2, 2]), "constant")
        self.assertEqual(classify_run([1.5, 1.5, 1.5]), "constant")

    def test_nondecreasing_with_adjacent_equals_is_rising(self):
        for values in [[1, 1, 2], [1, 2, 2], [-3, -3, 0, 4, 4]]:
            with self.subTest(values=values):
                self.assertEqual(classify_run(values), "rising")

    def test_nonincreasing_with_adjacent_equals_is_falling(self):
        for values in [[2, 2, 1], [2, 1, 1], [5, 5, 2, 0, 0, -1]]:
            with self.subTest(values=values):
                self.assertEqual(classify_run(values), "falling")

    def test_strict_and_mixed_sequences(self):
        self.assertEqual(classify_run([-1, 0, 3.5]), "rising")
        self.assertEqual(classify_run([8, 2, -4]), "falling")
        self.assertEqual(classify_run([1, 3, 2]), "mixed")
        self.assertEqual(classify_run([3, 1, 2]), "mixed")

    def test_wrong_container_or_element_types(self):
        with self.assertRaises(TypeError):
            classify_run((1, 2))
        with self.assertRaises(TypeError):
            classify_run("123")
        for values in [[True], [False, 1], ["1"], [None], [1, object()]]:
            with self.subTest(values=values):
                with self.assertRaises(TypeError):
                    classify_run(values)

    def test_non_finite_numbers(self):
        for value in [math.nan, math.inf, -math.inf]:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    classify_run([0, value])

    def test_input_is_not_mutated(self):
        values = [1, 1, 3, 5]
        before = list(values)
        self.assertEqual(classify_run(values), "rising")
        self.assertEqual(values, before)


if __name__ == "__main__":
    unittest.main()

